function decodeHtmlEntities(str) {
  if (!str) return '';
  var entities = {
    'quot': '"',
    'apos': "'",
    '#39': "'",
    'lt': '<',
    'gt': '>',
    'nbsp': ' ',
    'amp': '&'
  };
  var s = str
    .replace(/&#(\d+);/g, function(m, dec) {
      try { return String.fromCodePoint(parseInt(dec, 10)); } catch (e) { return m; }
    })
    .replace(/&#x([0-9a-f]+);/gi, function(m, hex) {
      try { return String.fromCodePoint(parseInt(hex, 16)); } catch (e) { return m; }
    });
  for (var round = 0; round < 2; round++) {
    s = s.replace(/&(quot|apos|#39|lt|gt|nbsp|amp);/gi, function(m, name) {
      return entities[name.toLowerCase()] || m;
    });
  }
  return s;
}

function stripTags(str) {
  if (!str) return '';
  return str.replace(/<[^>]+>/g, '');
}

function cleanText(str) {
  if (!str) return '';
  var s = stripTags(str);
  s = decodeHtmlEntities(s);
  s = stripTags(s);
  return s.trim();
}

function getTag(tag, text) {
  var regex = new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  var match = text.match(regex);
  if (!match) return '';
  return match[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1').trim();
}

function getLink(text) {
  var altMatch = text.match(/<link\b[^>]*\brel=["']alternate["'][^>]*\bhref=["']([^"']+)["'][^>]*\/?>/i)
    || text.match(/<link\b[^>]*\bhref=["']([^"']+)["'][^>]*\brel=["']alternate["'][^>]*\/?>/i);
  if (altMatch) return decodeHtmlEntities(altMatch[1].trim());

  var anyHrefMatch = text.match(/<link\b[^>]*\bhref=["']([^"']+)["'][^>]*\/?>/i);
  if (anyHrefMatch) return decodeHtmlEntities(anyHrefMatch[1].trim());

  return decodeHtmlEntities(getTag('link', text));
}

var sources = [];
try { sources = $('Источники').all(); } catch (e) {}

var inputItems = $input.all();
var result = [];

for (var idx = 0; idx < inputItems.length; idx++) {
  var item = inputItems[idx];
  var xml = item.json.data || '';
  if (!xml) continue;

  var src = item.json.name;
  if (!src) {
    var pIdx = undefined;
    if (item.pairedItem !== undefined && item.pairedItem !== null) {
      if (typeof item.pairedItem === 'number') {
        pIdx = item.pairedItem;
      } else if (typeof item.pairedItem === 'object') {
        pIdx = item.pairedItem.item !== undefined ? item.pairedItem.item : (Array.isArray(item.pairedItem) ? item.pairedItem[0]?.item : undefined);
      }
    }
    if (pIdx !== undefined && sources[pIdx]?.json?.name) {
      src = sources[pIdx].json.name;
    } else if (sources[idx]?.json?.name) {
      src = sources[idx].json.name;
    }
  }
  if (!src) src = 'News';

  var isAtom = /<entry\b[^>]*>/i.test(xml);
  var splitRegex = isAtom ? /<entry\b[^>]*>/i : /<item\b[^>]*>/i;
  var closeTagRegex = isAtom ? /<\/entry>/i : /<\/item>/i;

  var parts = xml.split(splitRegex);
  for (var i = 1; i < parts.length && i <= 5; i++) {
    var b = parts[i].split(closeTagRegex)[0];
    var title = cleanText(getTag('title', b));
    var url = getLink(b);
    var rawContent = getTag('description', b)
      || getTag('summary', b)
      || getTag('content', b);
    var content = cleanText(rawContent);
    var date = isAtom
      ? (getTag('updated', b) || getTag('published', b) || getTag('pubDate', b))
      : (getTag('pubDate', b) || getTag('dc:date', b) || getTag('date', b));

    if (title && url) {
      result.push({ json: { source: src, title: title, url: url, content: content, date: date } });
    }
  }
}
return result;

const TRACKING_PARAMS = new Set([
  'fbclid',
  'gclid',
  'at_medium',
  'at_campaign',
  'ref',
  'mc_cid',
  'mc_eid',
]);

function isTrackingParam(key) {
  const lower = key.toLowerCase();
  return lower.startsWith('utm_') || TRACKING_PARAMS.has(lower);
}

function normalizeUrl(rawUrl) {
  const trimmed = String(rawUrl || '').trim();
  if (!trimmed) return '';
  try {
    const u = new URL(trimmed);
    u.hash = '';
    const kept = [];
    for (const [k, v] of u.searchParams.entries()) {
      if (!isTrackingParam(k)) {
        kept.push([k, v]);
      }
    }
    kept.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0)));
    const sp = new URLSearchParams();
    for (const [k, v] of kept) {
      sp.append(k, v);
    }
    u.search = sp.toString() ? '?' + sp.toString() : '';
    if (u.pathname.length > 1) {
      u.pathname = u.pathname.replace(/\/+$/, '') || '/';
    }
    let out = u.toString();
    if (u.pathname === '/' && !u.search) {
      out = out.replace(/\/+$/, '');
    }
    return out;
  } catch (e) {
    return trimmed.split('#')[0].replace(/\/+$/, '');
  }
}

const seen = new Set(
  $('Чтение Базы').all()
    .map(i => normalizeUrl(i.json.url))
    .filter(Boolean)
);

const news = $input.all();
const cutoffMs = Date.now() - 24 * 60 * 60 * 1000;

const freshCandidates = [];
for (const n of news) {
  if (!n.json.url) continue;
  if (!n.json.title || n.json.title.trim() === '') continue;
  if (!n.json.date) continue;
  const ts = new Date(n.json.date).getTime();
  if (Number.isNaN(ts) || ts <= cutoffMs) continue;
  freshCandidates.push({ item: n, ts });
}
freshCandidates.sort((a, b) => b.ts - a.ts);

const bySource = new Map();
for (const { item: n, ts } of freshCandidates) {
  const normUrl = normalizeUrl(n.json.url);
  if (!normUrl || seen.has(normUrl)) continue;
  seen.add(normUrl);

  const src = n.json.source || 'News';
  if (!bySource.has(src)) bySource.set(src, []);
  bySource.get(src).push({
    json: {
      source: src,
      title: n.json.title,
      url: n.json.url,
      normalizedUrl: normUrl,
      content: n.json.content,
      date: n.json.date,
    },
    _ts: ts,
  });
}

const queues = Array.from(bySource.values());
queues.sort((a, b) => b[0]._ts - a[0]._ts);

const selected = [];
let round = 0;
while (selected.length < 10) {
  let addedInRound = false;
  for (const q of queues) {
    if (round < q.length) {
      selected.push({ json: q[round].json });
      addedInRound = true;
      if (selected.length >= 10) break;
    }
  }
  if (!addedInRound) break;
  round++;
}

return selected;

// Берем полные данные из фильтра, игнорируя обрезанные данные от базы
const items = $('Фильтр Дубликатов').all();
if (items.length === 0) return [];

const newsList = items.map((n, i) => ({
  id: i,
  title: n.json.title || '',
  text: (n.json.content || '').substring(0, 600),
}));

const promptText = `You are a professional translator.
Task: Translate news to Russian.

RULES:
1. Translate "title" -> "ru_title".
2. Translate "text" -> "ru_text".
3. If an item is already in Russian, keep it in Russian with light cleanup instead of translating.
4. Output ONLY a valid JSON array.

INPUT:
${JSON.stringify(newsList)}`;

return [{
  json: {
    model: 'gemma-4-e4b',
    messages: [
      { role: 'system', content: 'You strictly output JSON arrays and output all news in Russian.' },
      { role: 'user', content: promptText },
    ],
    temperature: 0.1,
    max_tokens: 8192,
  },
}];

function extractArray(parsed) {
  if (Array.isArray(parsed)) return parsed;
  if (parsed && typeof parsed === 'object') {
    for (const key of ['items', 'news', 'data', 'results', 'articles', 'output']) {
      if (Array.isArray(parsed[key])) return parsed[key];
    }
    for (const val of Object.values(parsed)) {
      if (Array.isArray(val)) return val;
    }
  }
  return null;
}

let aiData = [];
let llmOk = false;
try {
  const aiRaw = $input.first()?.json?.choices?.[0]?.message?.content;
  if (typeof aiRaw === 'string' && aiRaw.trim() !== '') {
    const cleaned = aiRaw
      .replace(/<think>[\s\S]*?<\/think>/gi, '')
      .replace(/```(?:json)?\s*/gi, '')
      .replace(/```/g, '')
      .trim();

    let parsed;
    let hasParsed = false;
    try {
      parsed = JSON.parse(cleaned);
      hasParsed = true;
    } catch (_) {
      const firstObj = cleaned.indexOf('{');
      const firstArr = cleaned.indexOf('[');
      const candidates = [];
      if (firstObj !== -1 && (firstArr === -1 || firstObj < firstArr)) {
        candidates.push(/\{[\s\S]*\}/, /\[[\s\S]*\]/);
      } else {
        candidates.push(/\[[\s\S]*\]/, /\{[\s\S]*\}/);
      }
      for (const re of candidates) {
        const m = cleaned.match(re);
        if (!m) continue;
        try {
          parsed = JSON.parse(m[0]);
          hasParsed = true;
          break;
        } catch (__) {}
      }
    }

    if (hasParsed) {
      const extracted = extractArray(parsed);
      if (Array.isArray(extracted)) {
        const validObjects = extracted.filter(item => item && typeof item === 'object' && !Array.isArray(item));
        if (extracted.length === 0 || validObjects.length > 0) {
          aiData = validObjects;
          llmOk = true;
        }
      }
    }
  }
} catch (e) {
  console.error('Ошибка парсинга:', e.message);
}

if (!llmOk) {
  return [];
}

const originals = $('Фильтр Дубликатов').all();

return originals.map((origItem, i) => {
  const orig = origItem.json;
  const ai = aiData.find(item =>
    item.id !== undefined
    && item.id !== null
    && String(item.id).trim() !== ''
    && Number(item.id) === i
  );

  const selected = Boolean(ai);
  const finalTitle = (ai && ai.ru_title && String(ai.ru_title).trim() !== '') ? ai.ru_title : orig.title;
  const finalContent = (ai && ai.ru_text && String(ai.ru_text).trim() !== '') ? ai.ru_text : orig.content;

  return {
    json: {
      selected,
      title: finalTitle,
      content: (finalContent || '').substring(0, 800),
      url: orig.url,
      normalizedUrl: orig.normalizedUrl || orig.url,
      source: orig.source,
    },
  };
});

